{"file_path": "src/lib/schemas/firestore-schemas.ts", "initial_content": "/**
 * Firestore Collection Validation Schemas
 * 
 * Centralized Zod schemas for all Firestore collections to ensure data integrity
 * and consistency across client and server operations.
 * 
 * Usage:
 * ```typescript
 * import { ProjectDocumentSchema } from '@/lib/schemas/firestore-schemas';
 * 
 * const validated = ProjectDocumentSchema.parse(data);
 * ```
 */

import { z } from 'zod';
import { UserRoleSchema } from '@/lib/models/user-validation';
import { 
  LanguageSchema, 
  ToneSchema, 
  BehaviorSchema, 
  CitationStyleSchema 
} from '@/lib/models/control-types';

// ============================================================================
// Common Base Schemas (reused across collections)
// ============================================================================

/**
 * ISO datetime string validation
 */
export const ISODateTimeSchema = z.string().datetime('Invalid ISO datetime format');

/**
 * UUID v4 validation
 */
export const UUIDSchema = z.string().uuid('Invalid UUID format');

/**
 * Firebase UID validation (22-28 alphanumeric characters)
 */
export const FirebaseUIDSchema = z.string().min(10).max(128);

/**
 * Email validation
 */
export const EmailSchema = z.string().email('Invalid email address');

/**
 * URL validation with empty string fallback
 */
export const URLOrEmptySchema = z.string().url('Invalid URL').or(z.string().length(0));

/**
 * Metadata for all documents with timestamps
 */
export const DocumentMetadataSchema = z.object({
  createdAt: ISODateTimeSchema,
  updatedAt: ISODateTimeSchema,
  createdBy: FirebaseUIDSchema.optional(),
  updatedBy: FirebaseUIDSchema.optional(),
});

// ============================================================================
// USERS Collection
// ============================================================================

/**
 * User Profile Document Schema
 * Location: /users/{userId}
 */
export const UserDocumentSchema = z.object({
  id: FirebaseUIDSchema,
  name: z.string().min(1, 'Name is required').max(200),
  email: EmailSchema,
  role: UserRoleSchema,
  credits: z.number().int().min(0).default(0),
  bio: z.string().max(1000).optional(),
  profilePictureUrl: URLOrEmptySchema.optional(),
  hasCompletedOnboarding: z.boolean().default(false),
  apiKeys: z.record(z.string(), z.string()).optional(),
  lastDailyCreditUpdate: ISODateTimeSchema.optional(),
  teams: z.array(UUIDSchema).default([]),
  createdAt: ISODateTimeSchema,
  updatedAt: ISODateTimeSchema,
});

export type UserDocument = z.infer<typeof UserDocumentSchema>;

/**
 * Partial user document for updates
 */
export const PartialUserDocumentSchema = UserDocumentSchema.partial().extend({
  id: FirebaseUIDSchema.optional(),
});

// ============================================================================
// PROJECTS Collection
// ============================================================================

/**
 * Project Metadata Schema
 */
export const ProjectMetadataSchema = z.object({
  author: FirebaseUIDSchema,
  version: z.string().regex(/^\d+\.\d+\.\d+$/, 'Version must be semver format'),
  created: ISODateTimeSchema,
  updated: ISODateTimeSchema,
});

/**
 * Project Settings Schema
 */
export const ProjectSettingsSchema = z.object({
  language: LanguageSchema.optional(),
  complexity: z.number().min(0).max(100).optional(),
  formality: z.number().min(0).max(100).optional(),
  tone: ToneSchema.optional(),
  behaviors: z.array(BehaviorSchema).optional(),
  rules: z.array(z.string().max(500)).optional(),
  constraints: z.array(z.string().max(500)).optional(),
  citationStyle: CitationStyleSchema.optional(),
});

/**
 * Project Document Schema
 * Location: /projects/{projectId}
 */
export const ProjectDocumentSchema = z.object({
  id: UUIDSchema,
  name: z.string().min(1, 'Project name is required').max(200),
  description: z.string().max(1000).optional(),
  projectDescription: z.string().max(5000).optional(),
  projectType: z.string().max(100).optional(),
  specialization: z.string().max(100).optional(),
  university: z.string().max(200).optional(),
  supervisor: z.string().max(200).optional(),
  course: z.string().max(200).optional(),
  educationalLevel: z.string().max(100).optional(),
  teamMembers: z.array(z.string().max(200)).optional(),
  logoUrl: URLOrEmptySchema.optional(),
  universityLogoUrl: URLOrEmptySchema.optional(),
  tableOfContentsMarkdown: z.string().max(10000).optional(),

  // Content structure - stored as nested objects
  content: z.array(z.object({
    id: UUIDSchema,
    type: z.enum(['chapter', 'section']),
    title: z.string().max(500),
    content: z.string().optional(),
    sections: z.array(z.any()).optional(), // Nested sections for chapters
  })).optional(),

  externalContext: z.array(z.object({
    id: UUIDSchema,
    fileName: z.string().max(500),
    type: z.enum(['context', 'reference', 'example']),
    content: z.string().optional(),
  })).optional(),

  // Global settings
  ...ProjectSettingsSchema.shape,

  // Metadata
  meta: ProjectMetadataSchema.optional(),
  teamId: UUIDSchema.optional(),
  createdAt: ISODateTimeSchema,
  updatedAt: ISODateTimeSchema,
});

export type ProjectDocument = z.infer<typeof ProjectDocumentSchema>;

/**
 * Partial project document for updates
 */
export const PartialProjectDocumentSchema = ProjectDocumentSchema.partial().extend({
  id: UUIDSchema.optional(),
});

// ============================================================================
// TEAMS Collection
// ============================================================================

/**
 * Team Document Schema
 * Location: /teams/{teamId}
 */
export const TeamDocumentSchema = z.object({
  id: UUIDSchema,
  name: z.string().min(1, 'Team name is required').max(200),
  description: z.string().max(1000).optional(),
  ownerId: FirebaseUIDSchema,
  members: z.array(FirebaseUIDSchema).default([]),
  createdAt: ISODateTimeSchema,
  updatedAt: ISODateTimeSchema,
});

export type TeamDocument = z.infer<typeof TeamDocumentSchema>;

/**
 * Team Member Subcollection Schema
 * Location: /teams/{teamId}/members/{memberId}
 */
export const TeamMemberSchema = z.object({
  id: FirebaseUIDSchema,
  userId: FirebaseUIDSchema,
  role: z.enum(['owner', 'admin', 'member']),
  joinedAt: ISODateTimeSchema,
});

export type TeamMember = z.infer<typeof TeamMemberSchema>;

// ============================================================================
// TRANSACTIONS Collection
// ============================================================================

/**
 * Transaction Document Schema
 * Location: /transactions/{transactionId}
 */
export const TransactionDocumentSchema = z.object({
  id: UUIDSchema,
  userId: FirebaseUIDSchema,
  planId: z.string().max(100),
  planName: z.string().max(200),
  credits: z.number().int().min(1),
  price: z.number().min(0),
  userName: z.string().max(200),
  userEmail: EmailSchema,
  status: z.enum(['pending', 'verified', 'rejected']),
  proofUrl: URLOrEmptySchema,
  adminNotes: z.string().max(1000).optional(),
  verifiedAt: ISODateTimeSchema.optional(),
  verifiedBy: FirebaseUIDSchema.optional(),
  createdAt: ISODateTimeSchema,
});

export type TransactionDocument = z.infer<typeof TransactionDocumentSchema>;

/**
 * Partial transaction document for updates (admins only)
 */
export const PartialTransactionDocumentSchema = TransactionDocumentSchema.partial().extend({
  id: UUIDSchema.optional(),
  status: z.enum(['pending', 'verified', 'rejected']).optional(),
});

// ============================================================================
// AGENT GENERATIONS Collection (Logs)
// ============================================================================

/**
 * Agent Generation Log Document Schema
 * Location: /agent_generations/{logId}
 */
export const AgentGenerationLogSchema = z.object({
  id: UUIDSchema,
  userId: FirebaseUIDSchema,
  agentId: z.string().max(100),
  agentName: z.string().max(200),
  prompt: z.string().max(10000),
  response: z.string().optional(),
  inputTokens: z.number().int().min(0).optional(),
  outputTokens: z.number().int().min(0).optional(),
  model: z.string().max(100),
  creditsUsed: z.number().min(0),
  status: z.enum(['pending', 'completed', 'failed']),
  errorMessage: z.string().optional(),
  projectId: UUIDSchema.optional(),
  sectionId: UUIDSchema.optional(),
  createdAt: ISODateTimeSchema,
  completedAt: ISODateTimeSchema.optional(),
});

export type AgentGenerationLog = z.infer<typeof AgentGenerationLogSchema>;

// ============================================================================
// PUBLIC CONFIGURATION Collections
// ============================================================================

/**
 * Feature Flag Document Schema
 * Location: /features/{featureId}
 */
export const FeatureDocumentSchema = z.object({
  id: z.string().max(100),
  name: z.string().max(200),
  description: z.string().max(1000).optional(),
  enabled: z.boolean(),
  rolloutPercentage: z.number().min(0).max(100).optional(),
  config: z.record(z.any()).optional(),
  createdAt: ISODateTimeSchema,
  updatedAt: ISODateTimeSchema,
});

export type FeatureDocument = z.infer<typeof FeatureDocumentSchema>;

/**
 * Agent Definition Document Schema
 * Location: /agents/{agentId}
 */
export const AgentDocumentSchema = z.object({
  id: z.string().max(100),
  name: z.string().max(200),
  description: z.string().max(1000),
  category: z.string().max(100),
  icon: z.string().max(500).optional(),
  enabled: z.boolean(),
  model: z.string().max(100),
  systemPrompt: z.string().max(10000),
  inputSchema: z.record(z.any()).optional(),
  outputSchema: z.record(z.any()).optional(),
  creditCost: z.number().min(0).default(1),
  createdAt: ISODateTimeSchema,
  updatedAt: ISODateTimeSchema,
});

export type AgentDocument = z.infer<typeof AgentDocumentSchema>;

/**
 * Agent Category Document Schema
 * Location: /agent_categories/{categoryId}
 */
export const AgentCategorySchema = z.object({
  id: z.string().max(100),
  name: z.string().max(200),
  description: z.string().max(1000).optional(),
  icon: z.string().max(500).optional(),
  displayOrder: z.number().int().default(0),
  createdAt: ISODateTimeSchema,
});

export type AgentCategory = z.infer<typeof AgentCategorySchema>;

/**
 * Section Definition Document Schema
 * Location: /sections/{sectionId}
 */
export const SectionDefinitionSchema = z.object({
  id: z.string().max(100),
  name: z.string().max(200),
  description: z.string().max(1000).optional(),
  type: z.string().max(100),
  enabled: z.boolean(),
  defaultPromptTemplate: z.string().max(10000).optional(),
  guidelines: z.array(z.string().max(500)).optional(),
  createdAt: ISODateTimeSchema,
  updatedAt: ISODateTimeSchema,
});

export type SectionDefinition = z.infer<typeof SectionDefinitionSchema>;

// ============================================================================
// TEMPLATES Collection
// ============================================================================

/**
 * Template Item Schema
 * Location: /templates/{type}/items/{templateId}
 */
export const TemplateItemSchema = z.object({
  id: UUIDSchema,
  name: z.string().max(200),
  description: z.string().max(1000).optional(),
  type: z.enum(['docx', 'pptx', 'report']),
  content: z.string().optional(),
  previewUrl: URLOrEmptySchema.optional(),
  enabled: z.boolean().default(true),
  createdAt: ISODateTimeSchema,
  updatedAt: ISODateTimeSchema,
});

export type TemplateItem = z.infer<typeof TemplateItemSchema>;

/**
 * Template Style Schema
 * Location: /templates/{type}/styles/{templateId}
 */
export const TemplateStyleSchema = z.object({
  id: UUIDSchema,
  name: z.string().max(200),
  type: z.enum(['docx', 'pptx']),
  styles: z.record(z.any()),
  fontFamily: z.string().max(100).optional(),
  fontSize: z.number().min(8).max(72).optional(),
  colors: z.object({
    primary: z.string().regex(/^#[0-9A-F]{6}$/i).optional(),
    secondary: z.string().regex(/^#[0-9A-F]{6}$/i).optional(),
    accent: z.string().regex(/^#[0-9A-F]{6}$/i).optional(),
  }).optional(),
  createdAt: ISODateTimeSchema,
  updatedAt: ISODateTimeSchema,
});

export type TemplateStyle = z.infer<typeof TemplateStyleSchema>;

// ============================================================================
// SETTINGS Collection
// ============================================================================

/**
 * Global Settings Document Schema
 * Location: /settings/defaults
 */
export const SettingsDocumentSchema = z.object({
  id: z.literal('defaults'),
  bankAccounts: z.array(z.object({
    accountName: z.string(),
    accountNumber: z.string(),
    bankName: z.string(),
    iban: z.string().optional(),
    swiftCode: z.string().optional(),
  })).optional(),
  paymentMethods: z.array(z.object({
    id: z.string(),
    name: z.string(),
    enabled: z.boolean(),
    config: z.record(z.any()).optional(),
  })).optional(),
  creditPlans: z.array(z.object({
    id: z.string(),
    name: z.string(),
    credits: z.number().int().positive(),
    price: z.number().positive(),
    enabled: z.boolean(),
  })).optional(),
  updatedAt: ISODateTimeSchema,
});

export type SettingsDocument = z.infer<typeof SettingsDocumentSchema>;

// ============================================================================
// DEVICE TOKENS Collection (Push Notifications)
// ============================================================================

/**
 * Device Token Document Schema
 * Location: /deviceTokens/{userId}
 */
export const DeviceTokenDocumentSchema = z.object({
  id: FirebaseUIDSchema,
  tokens: z.array(z.object({
    token: z.string().min(10),
    platform: z.enum(['web', 'ios', 'android']),
    addedAt: ISODateTimeSchema,
    lastUsedAt: ISODateTimeSchema.optional(),
  })).default([]),
  updatedAt: ISODateTimeSchema,
});

export type DeviceTokenDocument = z.infer<typeof DeviceTokenDocumentSchema>;

// ============================================================================
// INDEXED DOCUMENTS Collection (RAG System)
// ============================================================================

/**
 * Indexed Document Metadata Schema
 * Location: /indexed_documents/{docId}
 * Admin-only collection for RAG system document tracking
 */
export const IndexedDocumentSchema = z.object({
  id: UUIDSchema,
  fileName: z.string().max(500),
  fileSize: z.number().positive(),
  contentType: z.string().max(100),
  uploadedBy: FirebaseUIDSchema,
  uploadedAt: ISODateTimeSchema,
  indexedAt: ISODateTimeSchema,
  vectorStoreId: z.string().optional(),
  metadata: z.record(z.any()).optional(),
  status: z.enum(['pending', 'indexed', 'failed']),
  errorMessage: z.string().optional(),
});

export type IndexedDocument = z.infer<typeof IndexedDocumentSchema>;

// ============================================================================
// DYNAMIC FLOWS Collection
// ============================================================================

/**
 * Flow Configuration Document Schema
 * Location: /flows/{flowId}
 */
export const FlowDocumentSchema = z.object({
  id: UUIDSchema,
  name: z.string().max(200),
  description: z.string().max(1000).optional(),
  status: z.enum(['draft', 'active', 'archived']),
  steps: z.array(z.object({
    id: UUIDSchema,
    name: z.string().max(200),
    type: z.string().max(100),
    config: z.record(z.any()),
    inputs: z.array(z.string()).optional(),
    outputs: z.array(z.string()).optional(),
  })),
  createdBy: FirebaseUIDSchema,
  createdAt: ISODateTimeSchema,
  updatedAt: ISODateTimeSchema,
});

export type FlowDocument = z.infer<typeof FlowDocumentSchema>;

/**
 * Prompt Template Document Schema
 * Location: /prompts/{promptId}
 */
export const PromptTemplateSchema = z.object({
  id: UUIDSchema,
  name: z.string().max(200),
  description: z.string().max(1000).optional(),
  template: z.string().max(10000),
  status: z.enum(['draft', 'active', 'archived']),
  variables: z.array(z.object({
    name: z.string().max(100),
    type: z.string().max(50),
    required: z.boolean(),
  })).optional(),
  createdBy: FirebaseUIDSchema,
  createdAt: ISODateTimeSchema,
  updatedAt: ISODateTimeSchema,
});

export type PromptTemplate = z.infer<typeof PromptTemplateSchema>;

/**
 * Tool Registry Document Schema
 * Location: /tools/{toolId}
 */
export const ToolRegistrySchema = z.object({
  id: z.string().max(100),
  name: z.string().max(200),
  description: z.string().max(1000),
  type: z.string().max(100),
  inputSchema: z.record(z.any()),
  outputSchema: z.record(z.any()),
  enabled: z.boolean(),
  createdAt: ISODateTimeSchema,
  updatedAt: ISODateTimeSchema,
});

export type ToolRegistry = z.infer<typeof ToolRegistrySchema>;

/**
 * Execution Trace Document Schema
 * Location: /execution_traces/{traceId}
 */
export const ExecutionTraceSchema = z.object({
  id: UUIDSchema,
  userId: FirebaseUIDSchema,
  flowId: UUIDSchema,
  status: z.enum(['running', 'completed', 'failed']),
  steps: z.array(z.object({
    stepId: UUIDSchema,
    name: z.string(),
    status: z.enum(['pending', 'running', 'completed', 'failed']),
    inputs: z.record(z.any()).optional(),
    outputs: z.record(z.any()).optional(),
    error: z.string().optional(),
    duration: z.number().optional(),
  })).optional(),
  startedAt: ISODateTimeSchema,
  completedAt: ISODateTimeSchema.optional(),
  totalDuration: z.number().optional(),
});

export type ExecutionTrace = z.infer<typeof ExecutionTraceSchema>;

/**
 * Flow Test Result Document Schema
 * Location: /flow_tests/{testId}
 * Admin-only collection
 */
export const FlowTestResultSchema = z.object({
  id: UUIDSchema,
  flowId: UUIDSchema,
  testName: z.string().max(200),
  inputs: z.record(z.any()),
  expectedOutputs: z.record(z.any()),
  actualOutputs: z.record(z.any()).optional(),
  passed: z.boolean(),
  errorMessage: z.string().optional(),
  executedAt: ISODateTimeSchema,
});

export type FlowTestResult = z.infer<typeof FlowTestResultSchema>;

// ============================================================================
// Union Types for Generic Document Operations
// ============================================================================

/**
 * Union type of all Firestore document schemas for generic operations
 */
export type FirestoreDocument = 
  | UserDocument
  | ProjectDocument
  | TeamDocument
  | TransactionDocument
  | AgentGenerationLog
  | FeatureDocument
  | AgentDocument
  | TemplateItem
  | FlowDocument
  | ExecutionTrace;

/**
 * Map of collection names to their schemas for runtime validation
 */
export const FIRESTORE_SCHEMAS = {
  users: UserDocumentSchema,
  projects: ProjectDocumentSchema,
  teams: TeamDocumentSchema,
  transactions: TransactionDocumentSchema,
  agent_generations: AgentGenerationLogSchema,
  features: FeatureDocumentSchema,
  agents: AgentDocumentSchema,
  sections: SectionDefinitionSchema,
  templates: TemplateItemSchema,
  flows: FlowDocumentSchema,
  prompts: PromptTemplateSchema,
  tools: ToolRegistrySchema,
  execution_traces: ExecutionTraceSchema,
  indexed_documents: IndexedDocumentSchema,
  deviceTokens: DeviceTokenDocumentSchema,
} as const;

export type FirestoreCollectionName = keyof typeof FIRESTORE_SCHEMAS;

/**
 * Generic document validation function
 * @param collectionName - Name of the Firestore collection
 * @param data - Data to validate
 * @returns Validated data or throws ZodError
 */
export function validateFirestoreDocument(
  collectionName: FirestoreCollectionName,
  data: unknown
) {
  const schema = FIRESTORE_SCHEMAS[collectionName];
  if (!schema) {
    throw new Error(`Unknown collection: ${collectionName}`);
  }
  return schema.parse(data);
}

// ============================================================================
// Error Handler for Firestore Validation
// ============================================================================

export class FirestoreValidationError extends Error {
  constructor(
    message: string,
    public collection: string,
    public field?: string,
    public details?: unknown
  ) {
    super(message);
    this.name = 'FirestoreValidationError';
  }
}

/**
 * Safe validation function that converts ZodError to FirestoreValidationError
 * @param collectionName - Name of the collection
 * @param data - Data to validate
 * @returns Validated data or throws FirestoreValidationError
 */
export function safeValidateFirestoreDocument(
  collectionName: FirestoreCollectionName,
  data: unknown
) {
  try {
    return validateFirestoreDocument(collectionName, data);
  } catch (error) {
    if (error instanceof z.ZodError) {
      const firstError = error.errors[0];
      throw new FirestoreValidationError(
        `Validation failed for collection '${collectionName}': ${firstError?.message || 'Unknown error'}`,
        collectionName,
        firstError?.path.join('.'),
        error.errors
      );
    }
    throw error;
  }
}
"}

