};

/**
 * Converts error code to HTTP status
 */
function getStatusFromErrorCode(code: string): number {
  const upperCode = code.toUpperCase().replace(/-/g, '_');
  return ERROR_CODE_TO_STATUS[upperCode] || 500;
}

/**
 * Standardized error handler for API routes.
 * Converts all error types to consistent ApiErrorResponse format.
 * 
 * @param error - The error object (can be ZodError, FirebaseError, custom error, etc.)
 * @param defaultStatus - The HTTP status code to use if none can be determined
 * @returns A NextResponse object with a standardized error format
 */
export const handleApiError = (error: any, defaultStatus = 500): NextResponse<ApiErrorResponse> => {
  console.error("API Route Error:", error);

  let code = 'INTERNAL_ERROR';
  let message = 'An unexpected server error occurred';
  let status = defaultStatus;
  let field: string | undefined;
  let details: unknown;

  // 1. Handle Firestore Validation Errors
  if (error instanceof FirestoreValidationError) {
    code = 'VALIDATION_ERROR';
    message = error.message;
    field = error.field;
    details = error.details;
    status = 400;
  }

  // 2. Handle Zod validation errors
  else if (error instanceof ZodError) {
    code = 'VALIDATION_ERROR';
    const firstError = error.errors[0];
    message = firstError?.message || 'Request validation failed';
    field = firstError?.path.join('.') || undefined;
    details = error.flatten().fieldErrors;
    status = 400;
  }

  // 3. Handle Firebase errors
  else if (error instanceof CustomFirebaseError) {
    code = error.code.toUpperCase().replace(/-/g, '_');
    message = error.message;
    status = getStatusFromErrorCode(error.code);
  }

  // 4. Handle custom API errors with status
  else if (error.code && error.message) {
    code = typeof error.code === 'string' ? error.code.toUpperCase() : 'INTERNAL_ERROR';
    message = error.message;
    field = error.field;
    details = error.details;
    status = error.status || getStatusFromErrorCode(code);
  }

  // 5. Handle generic Error objects
  else if (error instanceof Error) {
    code = 'INTERNAL_ERROR';
    message = error.message || 'An unexpected server error occurred';
    status = defaultStatus;
  }

  // 6. Fallback for unknown error types
  else {
    code = 'INTERNAL_ERROR';
    message = typeof error === 'string' ? error : 'An unexpected server error occurred';
    status = defaultStatus;
  }

  const response: ApiErrorResponse = {
    success: false,
    error: {
      code,
      message: message || ERROR_CODE_MESSAGES[code] || message,
      ...(field && { field }),
      ...(details && { details }),
      timestamp: new Date().toISOString(),
    },
  };

  return NextResponse.json(response, { status });
};

/**
 * Standardized success response handler for API routes.
 * @param data - The data payload to send
 * @param status - The HTTP status code (default 200)
 * @returns A NextResponse object with standardized success format
 */
export const createApiResponse = <T = any>(
  data: T,
  status: number = 200
): NextResponse<ApiSuccessResponse<T>> => {
  const response: ApiSuccessResponse<T> = {
    success: true,
    data,
    timestamp: new Date().toISOString(),
  };
  return NextResponse.json(response, { status });
};"}

