      expect(() => UserDocumentSchema.parse(invalidUser)).toThrow(z.ZodError);
    });

    it('should reject invalid email format', () => {
      const invalidUser = {
        ...validUser,
        email: 'not-an-email',
      };
      expect(() => UserDocumentSchema.parse(invalidUser)).toThrow(z.ZodError);
    });

    it('should reject invalid role', () => {
