      expect(() => UserDocumentSchema.parse(invalidUser)).toThrow(z.ZodError);
    });

    it('should reject negative credits', () => {
      const invalidUser = {
        ...validUser,
        credits: -100,
      };
      expect(() => UserDocumentSchema.parse(invalidUser)).toThrow(z.ZodError);
