      expect(() => UserDocumentSchema.parse(invalidUser)).toThrow(z.ZodError);
    });

    it('should accept empty string for profilePictureUrl', () => {
      const userWithEmptyUrl = {
        ...validUser,
        profilePictureUrl: '',
