      expect(() => validateFirestoreDocument('unknown_collection' as any, {})).toThrow(Error);
    });

    it('should throw ZodError for invalid data', () => {
      expect(() => validateFirestoreDocument('users', { email: 'invalid' })).toThrow(z.ZodError);
    });
