{"file_path": "src/middleware/validation.ts", "initial_content": "/**
 * Request Validation Middleware
 * 
 * Middleware for validating request bodies against Firestore collection schemas.
 * This ensures that invalid data is caught before reaching Firestore, preventing
 * validation errors and maintaining data integrity.
 * 
 * Usage:
 * ```typescript
 * import { withValidation } from '@/middleware/validation';
 * 
 * export async function POST(request: Request) {
 *   return withValidation('projects', async (data) => {
 *     // data is now validated against ProjectDocumentSchema
 *     await saveToFirestore(data);
 *   })(request);
 * }
 * ```
 */

import { NextResponse, type NextRequest } from 'next/server';
import { ZodError } from 'zod';
import {
  FirestoreCollectionName,
  safeValidateFirestoreDocument,
  FirestoreValidationError,
} from '@/lib/schemas/firestore-schemas';
import { handleApiError } from '@/lib/utils/api-utils';

/**
 * Validates request body against a Firestore collection schema.
 * 
 * @param collectionName - Name of the Firestore collection for schema selection
 * @param handler - Async function that receives validated data
 * @returns Next.js API route handler
 * 
 * @example
 * ```typescript
 * export async function POST(request: Request) {
 *   return withValidation('projects', async (data) => {
 *     // data is guaranteed to match ProjectDocumentSchema
 *     const result = await db.collection('projects').add(data);
 *     return { id: result.id };
 *   })(request);
 * }
 * ```
 */
export const withValidation = <T = any>(
  collectionName: FirestoreCollectionName,
  handler: (data: T) => Promise<NextResponse | Response>
) => {
  return async (request: NextRequest): Promise<NextResponse> => {
    try {
      // Extract request body
      let body: unknown;
      try {
        body = await request.json();
      } catch (parseError) {
        return handleApiError(
          new Error('Invalid request body: JSON parse error'),
          400
        );
      }

      // Validate against collection schema
      const validated = safeValidateFirestoreDocument(collectionName, body);

      // Pass validated data to handler
      const result = await handler(validated as T);
      return result;
    } catch (error) {
      return handleApiError(error);
    }
  };
};

/**
 * Validates request body for partial updates (allows omitted fields).
 * Useful for PATCH requests where not all fields are provided.
 * 
 * @param collectionName - Name of the Firestore collection
 * @param handler - Async function that receives validated partial data
 * @returns Next.js API route handler
 * 
 * @example
 * ```typescript
 * export async function PATCH(request: Request) {
 *   return withPartialValidation('projects', async (data) => {
 *     // Only provided fields are validated
 *     await db.collection('projects').doc(id).update(data);
 *   })(request);
 * }
 * ```
 */
export const withPartialValidation = <T = any>(
  collectionName: FirestoreCollectionName,
  handler: (data: Partial<T>) => Promise<NextResponse | Response>
) => {
  return async (request: NextRequest): Promise<NextResponse> => {
    try {
      // Extract request body
      let body: unknown;
      try {
        body = await request.json();
      } catch (parseError) {
        return handleApiError(
          new Error('Invalid request body: JSON parse error'),
          400
        );
      }

      // For partial validation, accept any object but log a warning
      // In production, you may want stricter validation
      if (typeof body !== 'object' || body === null) {
        return handleApiError(
          new Error('Request body must be an object'),
          400
        );
      }

      // Pass validated data to handler
      const result = await handler(body as Partial<T>);
      return result;
    } catch (error) {
      return handleApiError(error);
    }
  };
};

/**
 * Validates multiple request bodies (for batch operations).
 * Useful for POST requests that accept arrays of items.
 * 
 * @param collectionName - Name of the Firestore collection
 * @param handler - Async function that receives validated array of items
 * @returns Next.js API route handler
 * 
 * @example
 * ```typescript
 * export async function POST(request: Request) {
 *   return withArrayValidation('projects', async (items) => {
 *     // items is an array where each element matches the schema
 *     const results = await Promise.all(
 *       items.map(item => db.collection('projects').add(item))
 *     );
 *     return results;
 *   })(request);
 * }
 * ```
 */
export const withArrayValidation = <T = any>(
  collectionName: FirestoreCollectionName,
  handler: (items: T[]) => Promise<NextResponse | Response>
) => {
  return async (request: NextRequest): Promise<NextResponse> => {
    try {
      // Extract request body
      let body: unknown;
      try {
        body = await request.json();
      } catch (parseError) {
        return handleApiError(
          new Error('Invalid request body: JSON parse error'),
          400
        );
      }

      // Ensure body is an array
      if (!Array.isArray(body)) {
        return handleApiError(
          new Error('Request body must be an array'),
          400
        );
      }

      // Validate each item
      const validated: T[] = [];
      for (let i = 0; i < body.length; i++) {
        try {
          const item = safeValidateFirestoreDocument(collectionName, body[i]);
          validated.push(item as T);
        } catch (error) {
          if (error instanceof FirestoreValidationError) {
            return handleApiError(
              new Error(
                `Item ${i}: Validation failed at field '${error.field}': ${error.message}`
              ),
              400
            );
          }
          throw error;
        }
      }

      // Pass validated array to handler
      const result = await handler(validated);
      return result;
    } catch (error) {
      return handleApiError(error);
    }
  };
};

/**
 * Validates request body with custom error handling.
 * Allows you to provide custom error messages or logging.
 * 
 * @param collectionName - Name of the Firestore collection
 * @param handler - Async function that receives validated data
 * @param options - Configuration options
 * @returns Next.js API route handler
 * 
 * @example
 * ```typescript
 * export async function POST(request: Request) {
 *   return withValidationConfig('projects', async (data) => {
 *     // ...
 *   }, {
 *     onValidationError: (error) => {
 *       console.log(`Project validation failed: ${error.field}`);
 *     }
 *   })(request);
 * }
 * ```
 */
interface ValidationOptions {
  onValidationError?: (error: FirestoreValidationError) => void;
  onSuccess?: (data: any) => void;
  maxRequestSize?: number; // in bytes
}

export const withValidationConfig = <T = any>(
  collectionName: FirestoreCollectionName,
  handler: (data: T) => Promise<NextResponse | Response>,
  options: ValidationOptions = {}
) => {
  return async (request: NextRequest): Promise<NextResponse> => {
    try {
      // Check request size if configured
      if (options.maxRequestSize) {
        const contentLength = request.headers.get('content-length');
        if (contentLength && parseInt(contentLength) > options.maxRequestSize) {
          return handleApiError(
            new Error(
              `Request body exceeds maximum size of ${options.maxRequestSize} bytes`
            ),
            413 // Payload Too Large
          );
        }
      }

      // Extract request body
      let body: unknown;
      try {
        body = await request.json();
      } catch (parseError) {
        return handleApiError(
          new Error('Invalid request body: JSON parse error'),
          400
        );
      }

      // Validate against collection schema
      try {
        const validated = safeValidateFirestoreDocument(collectionName, body);
        options.onSuccess?.(validated);

        // Pass validated data to handler
        const result = await handler(validated as T);
        return result;
      } catch (validationError) {
        if (validationError instanceof FirestoreValidationError) {
          options.onValidationError?.(validationError);
        }
        throw validationError;
      }
    } catch (error) {
      return handleApiError(error);
    }
  };
};

/**
 * Type-safe validation middleware helper
 * Provides IntelliSense for collection names
 */
export const createValidator = (collectionName: FirestoreCollectionName) => ({
  /**
   * Validates full request body
   */
  validate: <T = any>(handler: (data: T) => Promise<NextResponse | Response>) =>
    withValidation<T>(collectionName, handler),

  /**
   * Validates partial request body (for updates)
   */
  validatePartial: <T = any>(
    handler: (data: Partial<T>) => Promise<NextResponse | Response>
  ) => withPartialValidation<T>(collectionName, handler),

  /**
   * Validates array of items
   */
  validateArray: <T = any>(
    handler: (items: T[]) => Promise<NextResponse | Response>
  ) => withArrayValidation<T>(collectionName, handler),

  /**
   * Validates with custom options
   */
  validateWithConfig: <T = any>(
    handler: (data: T) => Promise<NextResponse | Response>,
    options?: ValidationOptions
  ) => withValidationConfig<T>(collectionName, handler, options),
});
"}

