```

### Pattern 2: PATCH Route (Update)

```typescript
import { withPartialValidation } from '@/middleware/validation';
import { createApiResponse, handleApiError } from '@/lib/utils/api-utils';

export async function PATCH(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;

  return withPartialValidation('projects', async (data) => {
    try {
      await db.collection('projects').doc(id).update(data);
      return createApiResponse({ success: true }, 200);
    } catch (error) {
      return handleApiError(error);
    }
  })(request);
}
